/* cppi::dc39ab9eac1b8524033c7f9eaaec7b514ba6c058041457c25cacf93506082da7 */
SELECT COUNT(*) FROM (SELECT * FROM (
select business_date, cppib_sec_id AS cppib_id,  from_currency_code AS from_currency, 
to_currency_code AS to_currency, type AS instrument_type, sub_type AS instrument_sub_type,
bid_value, askvalue AS ask_value, mid_value AS mid_value, business_date AS rate_date,
price_source_code AS price_source from market_uat.cppib_rates
where business_date = date('2025-06-24') AND "type" = 'CURRENCY' AND sub_type = 'CROSS_RATE' AND price_source_code = 'WM Company'
) z_q WHERE from_currency IN ('CAD')
) dbvrcnt

